# 3. Defining the checkpoint column structure


checkpoint_columns = [
    "annotation_order",
    "review_id",
    "business_id",
    "stars",
    "equal_period_4",
    "text_length",
    "text",
    "raw_output",
    "parse_success",
    "parse_method",
    "schema_valid",
    "range_valid",
    "logic_valid",
    "fully_valid",
    "validation_errors",
    "processing_error",
    "attempts_used",
    "processing_seconds",
    "annotation_timestamp",
    "annotation_json"
] + REVIEW_INDICATORS + [
    "confidence"
]


# 4. Defining an atomic checkpoint-saving function


def save_review_annotation_checkpoint(
    checkpoint_df,
    output_path
):
    """
    Save the checkpoint without replacing the existing file
    until the new file has been written successfully.
    """

    checkpoint_df = (
        checkpoint_df
        .drop_duplicates(
            subset=[
                "review_id"
            ],
            keep="last"
        )
        .sort_values(
            "annotation_order"
        )
        .reset_index(
            drop=True
        )
    )

    checkpoint_df = checkpoint_df.reindex(
        columns=checkpoint_columns
    )

    temporary_path = output_path.with_suffix(
        output_path.suffix + ".tmp"
    )

    checkpoint_df.to_csv(
        temporary_path,
        index=False
    )

    os.replace(
        temporary_path,
        output_path
    )


