def save_image_checkpoint(
    checkpoint_df,
    output_path
):
    """
    Save the image checkpoint atomically.
    """

    checkpoint_df = (
        checkpoint_df
        .drop_duplicates(
            subset=[
                "photo_id"
            ],
            keep="last"
        )
        .sort_values(
            "annotation_order"
        )
        .reset_index(
            drop=True
        )
        .reindex(
            columns=image_checkpoint_columns
        )
    )

    temporary_path = output_path.with_suffix(
        output_path.suffix + ".tmp"
    )

    checkpoint_df.to_csv(
        temporary_path,
        index=False
    )

    os.replace(
        temporary_path,
        output_path
    )



