# Manual Semantic Inspection of Final Photo Annotations


# In this step, I create a balanced manual validation sample
# from the completed image annotations.

# I display the selected Yelp photos together with their final
# Qwen annotations so that I can judge whether the visual scores
# are semantically reasonable.

# This cell does not modify the final annotation dataset.

from pathlib import Path

import matplotlib.pyplot as plt
import pandas as pd
from PIL import Image


# 1. Setting the final photo annotation file


PHOTO_FINAL_PATH = Path(
    "/content/drive/MyDrive/"
    "TUM_thesis_digital_marketing/"
    "processed/"
    "photo_annotations_final.csv"
)


# 2. Loading the completed photo annotations

manual_photo_df = pd.read_csv(
    PHOTO_FINAL_PATH,
    low_memory=False
)


print(
    "Final photo annotations loaded:",
    len(
        manual_photo_df
    )
)

print(
    "Unique restaurants:",
    manual_photo_df[
        "business_id"
    ].nunique()
)


# 3. Defining the image indicators to inspect


MANUAL_IMAGE_INDICATORS = [
    "visual_food_appeal",
    "presentation_quality",
    "portion_signal",
    "visual_cleanliness",
    "atmosphere_visual",
    "environment_visual",
    "exterior_condition",
    "crowding_signal",
    "negative_signals",
    "confidence"
]


# 4. Selecting a balanced sample across Yelp photo labels

PHOTOS_PER_LABEL = 6

MANUAL_SAMPLE_RANDOM_STATE = 42

manual_validation_parts = []


for photo_label in [
    "food",
    "inside",
    "outside",
    "drink"
]:

    label_df = (
        manual_photo_df[
            manual_photo_df[
                "label"
            ] == photo_label
        ]
        .copy()
    )

    sampled_label_df = (
        label_df
        .sample(
            n=min(
                PHOTOS_PER_LABEL,
                len(
                    label_df
                )
            ),
            random_state=(
                MANUAL_SAMPLE_RANDOM_STATE
            )
        )
    )

    manual_validation_parts.append(
        sampled_label_df
    )


manual_validation_df = (
    pd.concat(
        manual_validation_parts,
        ignore_index=True
    )
    .reset_index(
        drop=True
    )
)


manual_validation_df[
    "manual_sample_id"
] = range(
    1,
    len(
        manual_validation_df
    ) + 1
)


print(
    "\nManual validation sample size:",
    len(
        manual_validation_df
    )
)

print(
    "\nSample composition:"
)

display(
    manual_validation_df[
        "label"
    ]
    .value_counts()
    .reindex(
        [
            "food",
            "inside",
            "outside",
            "drink"
        ]
    )
    .rename(
        "photo_count"
    )
    .to_frame()
)


# 5. Verifying that all sampled image files are available


manual_validation_df[
    "image_exists"
] = (
    manual_validation_df[
        "image_path"
    ]
    .astype(str)
    .map(
        lambda path: Path(
            path
        ).exists()
    )
)


print(
    "\nImages available on disk:",
    int(
        manual_validation_df[
            "image_exists"
        ].sum()
    ),
    "/",
    len(
        manual_validation_df
    )
)


assert (
    manual_validation_df[
        "image_exists"
    ].all()
)


# 6. Displaying each image with its annotation


for _, row in (
    manual_validation_df
    .iterrows()
):

    print("\n" + "=" * 110)

    print(
        "MANUAL PHOTO VALIDATION "
        f"{int(row['manual_sample_id'])}/"
        f"{len(manual_validation_df)}"
    )

    print("=" * 110)

    print(
        "Photo ID:",
        row[
            "photo_id"
        ]
    )

    print(
        "Business ID:",
        row[
            "business_id"
        ]
    )

    print(
        "Yelp label:",
        row[
            "label"
        ]
    )

    caption_value = row.get(
        "caption",
        None
    )

    if (
        pd.isna(
            caption_value
        )
        or str(
            caption_value
        ).strip() == ""
    ):

        caption_value = "(no caption)"

    print(
        "Caption:",
        caption_value
    )

    print(
        "Image path:",
        row[
            "image_path"
        ]
    )


    # I display the customer-uploaded Yelp image.
    image = Image.open(
        row[
            "image_path"
        ]
    )

    plt.figure(
        figsize=(
            7,
            5
        )
    )

    plt.imshow(
        image
    )

    plt.axis(
        "off"
    )

    plt.title(
        f"Manual validation {int(row['manual_sample_id'])} "
        f"| Yelp label: {row['label']}"
    )

    plt.show()


    print(
        "\nFINAL QWEN ANNOTATION"
    )

    print(
        "-" * 110
    )

    for indicator in (
        MANUAL_IMAGE_INDICATORS
    ):

        value = row[
            indicator
        ]

        if pd.isna(
            value
        ):

            value = "null"

        print(
            f"{indicator:25s}: {value}"
        )

    print(
        "\nRAW MODEL OUTPUT"
    )

    print(
        "-" * 110
    )

    print(
        row[
            "raw_output"
        ]
    )


