# 1. Fitting sparse LLM-only penalized models

def fit_final_sparse_llm_only_model(
    data,
    scenario,
    construct,
    llm_feature
):

    model_df = (
        data[
            [
                "closed",
                llm_feature
            ]
        ]
        .dropna()
        .copy()
    )


    y = (
        model_df[
            "closed"
        ]
        .astype(int)
    )


    X = (
        model_df[
            [
                llm_feature
            ]
        ]
        .copy()
    )


    predictor_mean = (
        X[
            llm_feature
        ]
        .mean()
    )


    predictor_std = (
        X[
            llm_feature
        ]
        .std(
            ddof=0
        )
    )


    if predictor_std == 0:

        return {
            "scenario": scenario,
            "construct": construct,
            "construct_label": final_construct_labels[construct],
            "total_n": len(model_df),
            "closed_n": int(y.sum()),
            "penalized_odds_ratio": np.nan,
            "direction": "Zero variance"
        }


    X_standardized = (
        (
            X[
                llm_feature
            ]
            -
            predictor_mean
        )
        /
        predictor_std
    ).to_frame(
        name=llm_feature
    )


    model = LogisticRegression(
        penalty="l2",
        C=1.0,
        solver="lbfgs",
        max_iter=3000
    )


    model.fit(
        X_standardized,
        y
    )


    coefficient = (
        model.coef_[
            0,
            0
        ]
    )


    odds_ratio = np.exp(
        coefficient
    )


    if coefficient > 0:

        direction = "Higher change -> higher closure odds"

    elif coefficient < 0:

        direction = "Higher change -> lower closure odds"

    else:

        direction = "No directional association"


    return {
        "scenario": scenario,
        "construct": construct,
        "construct_label": final_construct_labels[construct],
        "total_n": len(model_df),
        "closed_n": int(y.sum()),
        "penalized_odds_ratio": odds_ratio,
        "direction": direction
    }


final_llm_only_sparse_rows = []


