# Image-Based Extension


# In this step, I estimate the final image-based analyses

# The image indicators are static restaurant-level variables
# because Yelp does not provide usable photo upload timestamps.

# I examine seven visual constructs:

# - visual food appeal;
# - presentation quality;
# - portion signal;
# - visual cleanliness;
# - visual atmosphere;
# - visual environment;
# - crowding.

# I first summarize the restaurant-level visual indicators.

# I then estimate:

# 1. one visual-only logistic regression for each construct;
# 2. one Yelp-adjusted model for each construct.

# The adjusted model controls for:
# - early pre-COVID average rating;
# - early pre-COVID log review count.

# All continuous predictors are standardized within each
# complete-case estimation sample.

# I report odds ratios, confidence intervals, p-values,
# average marginal effects, and incremental model-fit statistics.




import numpy as np
import pandas as pd
import statsmodels.api as sm
import warnings

from scipy.stats import chi2
from sklearn.metrics import roc_auc_score


# 1. Defining the seven visual constructs


final_image_features = [
    "visual_food_appeal_mean",
    "presentation_quality_mean",
    "portion_signal_mean",
    "visual_cleanliness_mean",
    "atmosphere_visual_mean",
    "environment_visual_mean",
    "crowding_signal_mean"
]


final_image_labels = {
    "visual_food_appeal_mean":
        "Visual food appeal",

    "presentation_quality_mean":
        "Presentation quality",

    "portion_signal_mean":
        "Portion signal",

    "visual_cleanliness_mean":
        "Visual cleanliness",

    "atmosphere_visual_mean":
        "Visual atmosphere",

    "environment_visual_mean":
        "Visual environment",

    "crowding_signal_mean":
        "Crowding"
}


final_image_baseline = [
    "period_avg_stars_early_pre",
    "log_review_count_early_pre"
]


# 2. Creating the final descriptive table

final_image_descriptive_df = (
    analysis_df[
        final_image_features
    ]
    .agg(
        [
            "count",
            "mean",
            "std",
            "median"
        ]
    )
    .T
    .reset_index()
    .rename(
        columns={
            "index": "feature",
            "count": "N",
            "std": "SD"
        }
    )
)


final_image_descriptive_df[
    "construct"
] = (
    final_image_descriptive_df[
        "feature"
    ]
    .map(
        final_image_labels
    )
)


final_image_descriptive_df = (
    final_image_descriptive_df[
        [
            "feature",
            "construct",
            "N",
            "mean",
            "SD",
            "median"
        ]
    ]
)


print(
    "\n" + "=" * 120
)

print(
    "FINAL DESCRIPTIVE STATISTICS FOR VISUAL INDICATORS"
)

print(
    "=" * 120
)


display(
    final_image_descriptive_df
    .round(
        4
    )
)


# 3. Function for one visual-only logistic regression


def fit_final_visual_only_model(
    data,
    visual_predictor,
    construct_label
):

    model_df = (
        data[
            [
                "closed",
                visual_predictor
            ]
        ]
        .dropna()
        .copy()
    )


    y = (
        model_df[
            "closed"
        ]
        .astype(int)
    )


    X = (
        model_df[
            [
                visual_predictor
            ]
        ]
        .copy()
    )


    predictor_mean = (
        X[
            visual_predictor
        ]
        .mean()
    )


    predictor_std = (
        X[
            visual_predictor
        ]
        .std(
            ddof=0
        )
    )


    if predictor_std == 0:

        raise ValueError(
            f"{construct_label}: zero predictor variance"
        )


    X_standardized = (
        (
            X[
                visual_predictor
            ]
            -
            predictor_mean
        )
        /
        predictor_std
    ).to_frame(
        name=visual_predictor
    )


    X_model = sm.add_constant(
        X_standardized,
        has_constant="add"
    )


    with warnings.catch_warnings():

        warnings.simplefilter(
            "ignore"
        )

        result = (
            sm.Logit(
                y,
                X_model
            )
            .fit(
                disp=False,
                maxiter=300
            )
        )


    coefficient = (
        result.params[
            visual_predictor
        ]
    )


    confidence_interval = (
        result
        .conf_int()
        .loc[
            visual_predictor
        ]
    )



    # Average marginal effect


    marginal_effects = (
        result
        .get_margeff(
            at="overall",
            method="dydx"
        )
    )


    marginal_effects_df = (
        marginal_effects
        .summary_frame()
    )


    average_marginal_effect = (
        marginal_effects_df
        .loc[
            visual_predictor,
            "dy/dx"
        ]
    )


    ame_ci_lower = (
        marginal_effects_df
        .loc[
            visual_predictor,
            "Conf. Int. Low"
        ]
    )


    if "Conf. Int. Hi." in (
        marginal_effects_df.columns
    ):

        ame_ci_upper = (
            marginal_effects_df
            .loc[
                visual_predictor,
                "Conf. Int. Hi."
            ]
        )

    else:

        ame_ci_upper = (
            marginal_effects_df
            .loc[
                visual_predictor,
                "Cont. Int. Hi."
            ]
        )


    predicted_probability = (
        result.predict(
            X_model
        )
    )


    auc = roc_auc_score(
        y,
        predicted_probability
    )


    pseudo_r2 = (
        1
        -
        (
            result.llf
            /
            result.llnull
        )
    )


    return {
        "feature": visual_predictor,
        "construct": construct_label,
        "N": len(model_df),
        "Closed": int(y.sum()),
        "odds_ratio": np.exp(
            coefficient
        ),
        "ci_lower": np.exp(
            confidence_interval.iloc[0]
        ),
        "ci_upper": np.exp(
            confidence_interval.iloc[1]
        ),
        "p_value": (
            result.pvalues[
                visual_predictor
            ]
        ),
        "average_marginal_effect": (
            average_marginal_effect
        ),
        "ame_ci_lower": ame_ci_lower,
        "ame_ci_upper": ame_ci_upper,
        "pseudo_r2": pseudo_r2,
        "auc": auc
    }


# 4. Estimating all visual-only models

final_visual_only_rows = []


for visual_feature in (
    final_image_features
):

    final_visual_only_rows.append(
        fit_final_visual_only_model(
            data=analysis_df,
            visual_predictor=visual_feature,
            construct_label=(
                final_image_labels[
                    visual_feature
                ]
            )
        )
    )


final_visual_only_df = (
    pd.DataFrame(
        final_visual_only_rows
    )
)


final_visual_only_df[
    "ame_percentage_points"
] = (
    final_visual_only_df[
        "average_marginal_effect"
    ]
    * 100
)


print(
    "\n" + "=" * 135
)

print(
    "FINAL VISUAL-ONLY LOGISTIC REGRESSION RESULTS"
)

print(
    "=" * 135
)


display(
    final_visual_only_df[
        [
            "construct",
            "N",
            "Closed",
            "odds_ratio",
            "ci_lower",
            "ci_upper",
            "p_value",
            "ame_percentage_points",
            "pseudo_r2",
            "auc"
        ]
    ]
    .round(
        4
    )
)


# 5. Function for one Yelp-adjusted image model


def fit_final_image_adjusted_model(
    data,
    visual_predictor,
    construct_label
):

    required_columns = (
        ["closed"]
        +
        final_image_baseline
        +
        [visual_predictor]
    )


    model_df = (
        data[
            required_columns
        ]
        .dropna()
        .copy()
    )


    y = (
        model_df[
            "closed"
        ]
        .astype(int)
    )


    all_predictors = (
        final_image_baseline
        +
        [visual_predictor]
    )


    X = (
        model_df[
            all_predictors
        ]
        .copy()
    )


    predictor_means = (
        X.mean()
    )


    predictor_stds = (
        X.std(
            ddof=0
        )
    )


    zero_variance_predictors = (
        predictor_stds[
            predictor_stds
            ==
            0
        ]
        .index
        .tolist()
    )


    if zero_variance_predictors:

        raise ValueError(
            f"{construct_label}: "
            f"zero-variance predictors "
            f"{zero_variance_predictors}"
        )


    X_standardized = (
        X
        -
        predictor_means
    ) / predictor_stds

    # Benchmark model


    X_benchmark = sm.add_constant(
        X_standardized[
            final_image_baseline
        ],
        has_constant="add"
    )


    with warnings.catch_warnings():

        warnings.simplefilter(
            "ignore"
        )

        benchmark_result = (
            sm.Logit(
                y,
                X_benchmark
            )
            .fit(
                disp=False,
                maxiter=300
            )
        )


    # Image-augmented model


    X_augmented = sm.add_constant(
        X_standardized,
        has_constant="add"
    )


    with warnings.catch_warnings():

        warnings.simplefilter(
            "ignore"
        )

        augmented_result = (
            sm.Logit(
                y,
                X_augmented
            )
            .fit(
                disp=False,
                maxiter=300
            )
        )


    coefficient = (
        augmented_result
        .params[
            visual_predictor
        ]
    )


    confidence_interval = (
        augmented_result
        .conf_int()
        .loc[
            visual_predictor
        ]
    )


    p_value = (
        augmented_result
        .pvalues[
            visual_predictor
        ]
    )


    # Average marginal effect


    marginal_effects = (
        augmented_result
        .get_margeff(
            at="overall",
            method="dydx"
        )
    )


    marginal_effects_df = (
        marginal_effects
        .summary_frame()
    )


    average_marginal_effect = (
        marginal_effects_df
        .loc[
            visual_predictor,
            "dy/dx"
        ]
    )


    ame_ci_lower = (
        marginal_effects_df
        .loc[
            visual_predictor,
            "Conf. Int. Low"
        ]
    )


    if "Conf. Int. Hi." in (
        marginal_effects_df.columns
    ):

        ame_ci_upper = (
            marginal_effects_df
            .loc[
                visual_predictor,
                "Conf. Int. Hi."
            ]
        )

    else:

        ame_ci_upper = (
            marginal_effects_df
            .loc[
                visual_predictor,
                "Cont. Int. Hi."
            ]
        )


    # Model-fit statistics


    benchmark_probability = (
        benchmark_result
        .predict(
            X_benchmark
        )
    )


    augmented_probability = (
        augmented_result
        .predict(
            X_augmented
        )
    )


    benchmark_auc = (
        roc_auc_score(
            y,
            benchmark_probability
        )
    )


    augmented_auc = (
        roc_auc_score(
            y,
            augmented_probability
        )
    )


    benchmark_pseudo_r2 = (
        1
        -
        (
            benchmark_result.llf
            /
            benchmark_result.llnull
        )
    )


    augmented_pseudo_r2 = (
        1
        -
        (
            augmented_result.llf
            /
            augmented_result.llnull
        )
    )


    lr_statistic = (
        2
        *
        (
            augmented_result.llf
            -
            benchmark_result.llf
        )
    )


    lr_p_value = (
        chi2.sf(
            lr_statistic,
            df=1
        )
    )


    return {
        "feature": visual_predictor,
        "construct": construct_label,
        "N": len(model_df),
        "Open": int(
            (
                y
                ==
                0
            )
            .sum()
        ),
        "Closed": int(
            y.sum()
        ),
        "odds_ratio": np.exp(
            coefficient
        ),
        "ci_lower": np.exp(
            confidence_interval.iloc[0]
        ),
        "ci_upper": np.exp(
            confidence_interval.iloc[1]
        ),
        "p_value": p_value,
        "average_marginal_effect": (
            average_marginal_effect
        ),
        "ame_ci_lower": ame_ci_lower,
        "ame_ci_upper": ame_ci_upper,
        "benchmark_aic": (
            benchmark_result.aic
        ),
        "augmented_aic": (
            augmented_result.aic
        ),
        "delta_aic": (
            augmented_result.aic
            -
            benchmark_result.aic
        ),
        "benchmark_pseudo_r2": (
            benchmark_pseudo_r2
        ),
        "augmented_pseudo_r2": (
            augmented_pseudo_r2
        ),
        "delta_pseudo_r2": (
            augmented_pseudo_r2
            -
            benchmark_pseudo_r2
        ),
        "benchmark_auc": (
            benchmark_auc
        ),
        "augmented_auc": (
            augmented_auc
        ),
        "delta_auc": (
            augmented_auc
            -
            benchmark_auc
        ),
        "lr_p_value": (
            lr_p_value
        )
    }


# 6. Estimating all seven adjusted image models


final_image_adjusted_rows = []


for visual_feature in (
    final_image_features
):

    final_image_adjusted_rows.append(
        fit_final_image_adjusted_model(
            data=analysis_df,
            visual_predictor=visual_feature,
            construct_label=(
                final_image_labels[
                    visual_feature
                ]
            )
        )
    )


final_image_adjusted_df = (
    pd.DataFrame(
        final_image_adjusted_rows
    )
)


final_image_adjusted_df[
    "ame_percentage_points"
] = (
    final_image_adjusted_df[
        "average_marginal_effect"
    ]
    * 100
)


final_image_adjusted_df[
    "ame_ci_lower_pp"
] = (
    final_image_adjusted_df[
        "ame_ci_lower"
    ]
    * 100
)


final_image_adjusted_df[
    "ame_ci_upper_pp"
] = (
    final_image_adjusted_df[
        "ame_ci_upper"
    ]
    * 100
)


# 7. Displaying final adjusted image results

print(
    "\n" + "=" * 150
)

print(
    "FINAL YELP-ADJUSTED IMAGE EXTENSION RESULTS"
)

print(
    "=" * 150
)


display(
    final_image_adjusted_df[
        [
            "construct",
            "N",
            "Closed",
            "odds_ratio",
            "ci_lower",
            "ci_upper",
            "p_value",
            "ame_percentage_points",
            "ame_ci_lower_pp",
            "ame_ci_upper_pp",
            "delta_aic",
            "delta_pseudo_r2",
            "delta_auc",
            "lr_p_value"
        ]
    ]
    .round(
        4
    )
)


# 8. Displaying any p < 0.05 adjusted associations

final_image_significant_df = (
    final_image_adjusted_df[
        final_image_adjusted_df[
            "p_value"
        ]
        <
        0.05
    ]
    .copy()
)


print(
    "\nADJUSTED IMAGE ASSOCIATIONS WITH p < 0.05"
)


display(
    final_image_significant_df[
        [
            "construct",
            "N",
            "Closed",
            "odds_ratio",
            "ci_lower",
            "ci_upper",
            "p_value",
            "ame_percentage_points",
            "delta_aic",
            "delta_pseudo_r2",
            "delta_auc"
        ]
    ]
    .round(
        4
    )
)



print(
    "\n" + "=" * 120
)

print(
    "FINAL IMAGE EXTENSION COMPLETE"
)

print(
    "=" * 120
)


print(
    "Visual constructs analysed:",
    len(
        final_image_adjusted_df
    )
)


print(
    "Adjusted associations with p < 0.05:",
    int(
        (
            final_image_adjusted_df[
                "p_value"
            ]
            <
            0.05
        )
        .sum()
    )
)

# Saving the Final Image-Extension Forest Plot


# In this figure, I summarize the final Yelp-adjusted image models.

# Each point shows the odds ratio for a one-standard-deviation
# increase in the visual indicator, and each horizontal line shows
# its 95% confidence interval.

# The vertical reference line at OR = 1 represents no association
# with Yelp endpoint closure.

# I create the figure directly from final_image_adjusted_df so that
# the plot uses the same results reported in the final analysis.


import matplotlib.pyplot as plt
import numpy as np



# 1. Preparing the final image-model results for plotting


final_image_forest_df = (
    final_image_adjusted_df[
        [
            "construct",
            "odds_ratio",
            "ci_lower",
            "ci_upper"
        ]
    ]
    .copy()
    .sort_values(
        "odds_ratio",
        ascending=False
    )
    .reset_index(
        drop=True
    )
)


# 2. Creating plotting positions


y_positions = np.arange(
    len(
        final_image_forest_df
    )
)


# 3. Drawing odds ratios and 95% confidence intervals

fig, ax = plt.subplots(
    figsize=(
        9,
        6
    )
)


ax.errorbar(
    final_image_forest_df[
        "odds_ratio"
    ],
    y_positions,
    xerr=[
        final_image_forest_df[
            "odds_ratio"
        ]
        -
        final_image_forest_df[
            "ci_lower"
        ],

        final_image_forest_df[
            "ci_upper"
        ]
        -
        final_image_forest_df[
            "odds_ratio"
        ]
    ],
    fmt="o",
    capsize=4
)


# 4. Adding numerical odds-ratio labels


for row_index, row in (
    final_image_forest_df.iterrows()
):

    ax.annotate(
        (
            f"OR={row['odds_ratio']:.2f} "
            f"[{row['ci_lower']:.2f}, "
            f"{row['ci_upper']:.2f}]"
        ),
        xy=(
            row[
                "ci_upper"
            ],
            row_index
        ),
        xytext=(
            8,
            0
        ),
        textcoords="offset points",
        va="center",
        fontsize=9
    )


# 5. Adding the no-association reference line


ax.axvline(
    1,
    linestyle="--",
    linewidth=1
)


# 6. Formatting the figure


ax.set_yticks(
    y_positions
)


ax.set_yticklabels(
    final_image_forest_df[
        "construct"
    ]
)


ax.set_xlabel(
    "Odds ratio for a one-standard-deviation higher visual score"
)


ax.set_title(
    "Associations of LLM-Derived Visual Indicators with Endpoint Closure"
)


ax.grid(
    axis="x",
    alpha=0.2
)


plt.tight_layout()



final_image_forest_path = (
    BASE_DIR
    /
    "image_visual_associations_forest.png"
)


plt.savefig(
    final_image_forest_path,
    dpi=300,
    bbox_inches="tight"
)


plt.show()


print(
    "Saved final image-extension forest plot to:"
)

print(
    final_image_forest_path
)